    def ratio_search(self):
        """Largest feasible member of the public ratio set (index form)."""
        cands = self.rset
        # the static bound prunes the top of the list: feasibility is monotone
        lo = 0
        hi = len(cands) - 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if self.static_ok(self.lowers(cands[mid])):
                lo = mid
            else:
                hi = mid - 1
        top = lo
        if top == 0:
            return 0
        if self.feasible(self.lowers(cands[top]))[0]:
            return top
        lo = 0
        hi = top - 1
        best = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if self.feasible(self.lowers(cands[mid]))[0]:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return best

